const API = "http://localhost:5000/api/auth"; // ← add at top of file

// ── Step 1: Register ──────────────────────────────────────────
const handleStep1 = async () => {
  setAlert(null);
  if (!validate()) return;
  setLoading(true);
  try {
    const res  = await fetch(`${API}/register`, {
      method:  "POST",
      headers: { "Content-Type": "application/json" },
      body:    JSON.stringify({
        full_name: `${firstName.trim()} ${lastName.trim()}`,
        email:     email.trim(),
        phone:     phone.trim(),
        password,
      }),
    });
    const data = await res.json();
    if (data.success) {
      setStep(2);
      startTimer();
    } else {
      setAlert({ type: "error", msg: data.message });
    }
  } catch {
    setAlert({ type: "error", msg: "Cannot connect to server. Please try again." });
  } finally {
    setLoading(false);
  }
};

// ── Step 2: Verify OTP ────────────────────────────────────────
const verifyOTP = async () => {
  setAlert(null);
  const otpVal = otp.replace(/\D/g, "");
  if (otpVal.length < 6) {
    setAlert({ type: "error", msg: "Please enter all 6 OTP digits." });
    return;
  }
  setLoading(true);
  try {
    const res  = await fetch(`${API}/verify-otp`, {
      method:  "POST",
      headers: { "Content-Type": "application/json" },
      body:    JSON.stringify({ phone: phone.trim(), otp: otpVal, purpose: "register" }),
    });
    const data = await res.json();
    if (data.success) {
      localStorage.setItem("token", data.token);
      localStorage.setItem("user",  JSON.stringify(data.user));
      setStep(3);
    } else {
      setAlert({ type: "error", msg: data.message });
    }
  } catch {
    setAlert({ type: "error", msg: "Cannot connect to server. Please try again." });
  } finally {
    setLoading(false);
  }
};

// ── Resend OTP ────────────────────────────────────────────────
const resendOTP = async () => {
  setOtp("");
  setAlert(null);
  try {
    const res  = await fetch(`${API}/resend-otp`, {
      method:  "POST",
      headers: { "Content-Type": "application/json" },
      body:    JSON.stringify({ phone: phone.trim(), purpose: "register" }),
    });
    const data = await res.json();
    if (data.success) {
      startTimer();
      setAlert({ type: "success", msg: "New OTP sent to your email." });
    } else {
      setAlert({ type: "error", msg: data.message });
    }
  } catch {
    setAlert({ type: "error", msg: "Failed to resend OTP. Try again." });
  }
};
